/**
 * Generates src/core/syntax-theme-index.js from the installed highlight.js themes.
 * Run with `npm run syntax-themes` after upgrading highlight.js.
 */
import { writeFile } from 'node:fs/promises';
import { fileURLToPath } from 'node:url';
import * as prettier from 'prettier';
import { syntaxThemes } from './syntax-themes.js';

const themes = await syntaxThemes();
const body = themes.map((t) => `  ${JSON.stringify(t.name)}: ${t.dark ? 1 : 0},`).join('\n');
const source = `// @ts-check
// Generated by scripts/generate-syntax-index.js — do not edit by hand.
/**
 * Every syntax theme name (converted from highlight.js), mapped to 1 for dark themes.
 * Used to validate \`syntax-theme\` attributes before any request.
 *
 * @module core/syntax-theme-index
 */

/** @type {Readonly<Record<string, 0 | 1>>} */
export const SYNTAX_THEME_INDEX = Object.freeze({
${body}
});
`;
const file = fileURLToPath(new URL('../src/core/syntax-theme-index.js', import.meta.url));
// Formatted like the rest of the code base, so CI can compare it with the committed file.
const options = { ...(await prettier.resolveConfig(file)), filepath: file };
await writeFile(file, await prettier.format(source, options));
console.log(`syntax-theme-index.js: ${themes.length} themes`);
